<?php
require_once __DIR__ . '/../api/db.php';
requireSuperAdmin();
$db=getDB();syncPromotionStatuses();
$adminId=(int)$_SESSION['superadmin_id'];$adminName=$_SESSION['superadmin_name']??'Admin';$flash='';$flashType='success';
function recLabel(?string $value):string{return ucwords(str_replace('_',' ',$value??''));}
function getRec(PDO $db,int $id,bool $lock=false):array|false{
 $sql="SELECT r.*,v.name venue_name,v.city,v.district,vo.name owner_name,vo.email owner_email,
 (SELECT status FROM promotion_payments p WHERE p.service_type='recommended_venue' AND p.service_id=r.id ORDER BY p.id DESC LIMIT 1) payment_status,
 (SELECT payment_method FROM promotion_payments p WHERE p.service_type='recommended_venue' AND p.service_id=r.id ORDER BY p.id DESC LIMIT 1) payment_method,
 (SELECT provider_reference FROM promotion_payments p WHERE p.service_type='recommended_venue' AND p.service_id=r.id AND p.status='paid' ORDER BY p.id DESC LIMIT 1) payment_reference,
 (SELECT paid_at FROM promotion_payments p WHERE p.service_type='recommended_venue' AND p.service_id=r.id AND p.status='paid' ORDER BY p.id DESC LIMIT 1) paid_at
 FROM recommended_venue_promotions r JOIN venues v ON v.id=r.venue_id JOIN venue_owners vo ON vo.id=r.owner_id WHERE r.id=?".($lock?' FOR UPDATE':'');
 $s=$db->prepare($sql);$s->execute([$id]);return $s->fetch();
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verifyCsrfToken($_POST['csrf_token']??'')){http_response_code(403);die('Your session expired. Please return and try again.');}
 $id=(int)($_POST['id']??0);$action=$_POST['action']??'';$reason=trim($_POST['reason']??'');
 try{
  if(!$id)throw new RuntimeException('Recommended Venue order not found.');
  $db->beginTransaction();$item=getRec($db,$id,true);if(!$item)throw new RuntimeException('Recommended Venue order not found.');
  $paid=$item['payment_status']==='paid'&&$item['payment_method']==='esewa';
  if($action==='save'){
   $venueId=(int)($_POST['venue_id']??0);$start=$_POST['starts_at']??'';
   $v=$db->prepare("SELECT id FROM venues WHERE id=? AND owner_id=? AND status='active'");$v->execute([$venueId,$item['owner_id']]);
   if(!$v->fetchColumn())throw new RuntimeException('Choose an active venue belonging to this owner.');
   if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)||!strtotime($start))throw new RuntimeException('Choose a valid placement start date.');
   $expiry=date('Y-m-d',strtotime($start.' +1 month'));$status=$item['status'];
   if($paid&&in_array($status,['active','scheduled'],true))$status=strtotime($start)>strtotime(date('Y-m-d'))?'scheduled':'active';
   $db->prepare("UPDATE recommended_venue_promotions SET venue_id=?,starts_at=?,expires_at=?,amount_npr=1000,status=? WHERE id=?")->execute([$venueId,$start,$expiry,$status,$id]);
   $flash='Recommendation details saved. Price remains NPR 1,000 for one month.';
  }elseif($action==='activate'){
   if(!$paid)throw new RuntimeException('Activation requires a completed owner payment through mock eSewa.');
   $start=$_POST['starts_at']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)||strtotime($start)<strtotime(date('Y-m-d')))throw new RuntimeException('Choose today or a future start date.');
   $expiry=date('Y-m-d',strtotime($start.' +1 month'));$status=strtotime($start)>strtotime(date('Y-m-d'))?'scheduled':'active';
   $db->prepare("UPDATE recommended_venue_promotions SET starts_at=?,expires_at=?,amount_npr=1000,status=?,approved_by=?,approved_at=NOW(),rejection_reason=NULL WHERE id=?")->execute([$start,$expiry,$status,$adminId,$id]);
   $flash=$status==='active'?'Recommendation activated now for one month.':'Recommendation approved and scheduled for one month.';
  }elseif($action==='reject'){
   if($item['status']!=='pending_review')throw new RuntimeException('Only an order awaiting review can be rejected.');
   $db->prepare("UPDATE recommended_venue_promotions SET status='rejected',rejection_reason=? WHERE id=?")->execute([$reason?:'Rejected by Super Admin',$id]);$flash='Recommendation rejected.';
  }elseif($action==='suspend'){
   if(!in_array($item['status'],['pending_review','scheduled','active'],true))throw new RuntimeException('This order cannot be suspended from its current status.');
   $db->prepare("UPDATE recommended_venue_promotions SET status='suspended',rejection_reason=? WHERE id=?")->execute([$reason?:'Suspended by Super Admin',$id]);$flash='Recommendation suspended.';
  }elseif($action==='restore'){
   if(!$paid)throw new RuntimeException('Only a mock eSewa-paid order can be restored.');
   if(!in_array($item['status'],['suspended','rejected','cancelled','expired'],true))throw new RuntimeException('This order does not need restoration.');
   $db->prepare("UPDATE recommended_venue_promotions SET starts_at=CURDATE(),expires_at=DATE_ADD(CURDATE(),INTERVAL 1 MONTH),status='pending_review',approved_by=NULL,approved_at=NULL,rejection_reason=NULL WHERE id=?")->execute([$id]);$flash='Paid order restored to Pending Review.';
  }elseif($action==='cancel'){
   $db->prepare("UPDATE recommended_venue_promotions SET status='cancelled',rejection_reason=? WHERE id=?")->execute([$reason?:'Cancelled by Super Admin',$id]);$flash='Recommendation cancelled and removed from placement.';
  }elseif($action==='delete'){
   if($paid){$db->prepare("UPDATE recommended_venue_promotions SET status='cancelled',rejection_reason=? WHERE id=?")->execute([$reason?:'Archived by Super Admin; payment history preserved',$id]);$flash='Paid recommendation archived. Financial and audit history were preserved.';}
   else{$db->prepare("DELETE FROM promotion_analytics WHERE promotion_type='recommended_venue' AND promotion_id=?")->execute([$id]);$db->prepare("DELETE FROM promotion_payments WHERE service_type='recommended_venue' AND service_id=? AND status<>'paid'")->execute([$id]);$db->prepare("DELETE FROM recommended_venue_promotions WHERE id=?")->execute([$id]);$flash='Unpaid recommendation permanently deleted.';}
  }else throw new RuntimeException('Unsupported recommendation action.');
  logAudit('manage_recommended_venue','Promotions','recommended_venue',$id,$action.' Recommended Venue order');$db->commit();
  if($action!=='delete'||$paid)createNotification((int)$item['owner_id'],'owner',(int)$item['tenant_id'],'Recommended Venue Updated',$flash,'system');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$flash=$e instanceof RuntimeException?$e->getMessage():'Unable to update the recommendation safely.';$flashType='error';if(!($e instanceof RuntimeException))error_log('Recommendation admin error: '.$e->getMessage());}
}
syncPromotionStatuses();
$statusFilter=$_GET['status']??'all';$paymentFilter=$_GET['payment']??'all';
$statuses=['all','pending_payment','pending_review','scheduled','active','expired','rejected','suspended','cancelled'];
if(!in_array($statusFilter,$statuses,true))$statusFilter='all';if(!in_array($paymentFilter,['all','paid','unpaid'],true))$paymentFilter='all';
$where=[];$params=[];if($statusFilter!=='all'){$where[]='r.status=?';$params[]=$statusFilter;}
if($paymentFilter==='paid')$where[]="EXISTS(SELECT 1 FROM promotion_payments px WHERE px.service_type='recommended_venue' AND px.service_id=r.id AND px.status='paid' AND px.payment_method='esewa')";
elseif($paymentFilter==='unpaid')$where[]="NOT EXISTS(SELECT 1 FROM promotion_payments px WHERE px.service_type='recommended_venue' AND px.service_id=r.id AND px.status='paid')";
$sql="SELECT r.*,v.name venue_name,v.city,v.district,vo.name owner_name,vo.email owner_email,
 (SELECT status FROM promotion_payments p WHERE p.service_type='recommended_venue' AND p.service_id=r.id ORDER BY p.id DESC LIMIT 1) payment_status,
 (SELECT payment_method FROM promotion_payments p WHERE p.service_type='recommended_venue' AND p.service_id=r.id ORDER BY p.id DESC LIMIT 1) payment_method,
 (SELECT provider_reference FROM promotion_payments p WHERE p.service_type='recommended_venue' AND p.service_id=r.id AND p.status='paid' ORDER BY p.id DESC LIMIT 1) payment_reference,
 (SELECT paid_at FROM promotion_payments p WHERE p.service_type='recommended_venue' AND p.service_id=r.id AND p.status='paid' ORDER BY p.id DESC LIMIT 1) paid_at,
 (SELECT COUNT(*) FROM promotion_analytics a WHERE a.promotion_type='recommended_venue' AND a.promotion_id=r.id AND a.event_type='impression') impressions,
 (SELECT COUNT(*) FROM promotion_analytics a WHERE a.promotion_type='recommended_venue' AND a.promotion_id=r.id AND a.event_type='click') clicks,
 (SELECT COUNT(*) FROM promotion_analytics a WHERE a.promotion_type='recommended_venue' AND a.promotion_id=r.id AND a.event_type='booking') bookings
 FROM recommended_venue_promotions r JOIN venues v ON v.id=r.venue_id JOIN venue_owners vo ON vo.id=r.owner_id".($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY r.created_at DESC';
$s=$db->prepare($sql);$s->execute($params);$orders=$s->fetchAll();
$venuesByOwner=[];foreach($db->query("SELECT id,owner_id,name,city FROM venues WHERE status='active' ORDER BY name")->fetchAll()as$v)$venuesByOwner[(int)$v['owner_id']][]=$v;
$stats=$db->query("SELECT COUNT(*) total,SUM(status='pending_review') pending_review,SUM(status='active') active,SUM(status='scheduled') scheduled FROM recommended_venue_promotions")->fetch();
$revenue=(float)$db->query("SELECT COALESCE(SUM(amount_npr),0) FROM promotion_payments WHERE service_type='recommended_venue' AND payment_method='esewa' AND status='paid'")->fetchColumn();
?>
