<form class="filters" method="get"><select name="status"><option value="all">All statuses</option><?php foreach(array_slice($statuses,1)as$status):?><option value="<?=htmlspecialchars($status)?>" <?=$statusFilter===$status?'selected':''?>><?=htmlspecialchars(recLabel($status))?></option><?php endforeach;?></select><select name="payment"><option value="all">All payments</option><option value="paid" <?=$paymentFilter==='paid'?'selected':''?>>Paid by mock eSewa</option><option value="unpaid" <?=$paymentFilter==='unpaid'?'selected':''?>>Unpaid</option></select><button class="btn btn-navy btn-sm">Apply</button><a class="btn btn-ghost btn-sm" href="recommended-promotions.php">Reset</a></form>
<section class="data-card"><div class="data-card-header"><h3>All recommendation orders</h3><span><?=count($orders)?> shown</span></div><?php if($orders):foreach($orders as$order):$paid=$order['payment_status']==='paid'&&$order['payment_method']==='esewa';?><article class="rec"><div class="head"><div><div class="title"><strong><?=htmlspecialchars($order['venue_name'])?></strong> <small>#<?=(int)$order['id']?></small></div><div class="meta"><strong>Owner:</strong> <?=htmlspecialchars($order['owner_name'])?> · <?=htmlspecialchars($order['owner_email'])?><br><strong>Location:</strong> <?=htmlspecialchars($order['city'].($order['district']?' · '.$order['district']:''))?> · <strong>Period:</strong> <?=htmlspecialchars($order['starts_at']??'-')?> to <?=htmlspecialchars($order['expires_at']??'-')?><br><strong>Submitted:</strong> <?=date('d M Y, g:i A',strtotime($order['created_at']))?><?php if($order['rejection_reason']):?> · <strong>Admin note:</strong> <?=htmlspecialchars($order['rejection_reason'])?><?php endif;?></div></div><div><span class="badge <?=htmlspecialchars($order['status'])?>"><?=htmlspecialchars(recLabel($order['status']))?></span> <span class="paid <?=$paid?'':'unpaid'?>"><?=$paid?'Paid · mock eSewa':'Payment pending'?></span></div></div>
<div class="meta"><?php if($paid):?><strong>Reference:</strong> <?=htmlspecialchars($order['payment_reference'])?> · <?=date('d M Y, g:i A',strtotime($order['paid_at']))?><?php else:?>No completed payment. This order cannot be activated.<?php endif;?></div><div class="metrics"><span><?=(int)$order['impressions']?> impressions</span><span><?=(int)$order['clicks']?> clicks</span><span><?=(int)$order['bookings']?> bookings</span><span>NPR <?=number_format((float)$order['amount_npr'])?></span></div>
