<div class="actions"><?php if($paid&&in_array($order['status'],['pending_review','scheduled'],true)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?=(int)$order['id']?>"><input type="hidden" name="starts_at" value="<?=htmlspecialchars(max(date('Y-m-d'),$order['starts_at']))?>"><button name="action" value="activate" class="btn btn-green btn-sm">Approve &amp; activate</button></form><?php endif;?><?php if(in_array($order['status'],['pending_review','scheduled','active'],true)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?=(int)$order['id']?>"><input class="reason" name="reason" placeholder="Suspension reason"><button name="action" value="suspend" class="btn btn-red btn-sm">Suspend</button></form><?php endif;?><?php if($paid&&in_array($order['status'],['suspended','rejected','cancelled','expired'],true)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?=(int)$order['id']?>"><button name="action" value="restore" class="btn btn-green btn-sm">Restore to review</button></form><?php endif;?><?php if(!in_array($order['status'],['cancelled','expired'],true)):?><form method="post" onsubmit="return confirm('Cancel this recommendation?')"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?=(int)$order['id']?>"><button name="action" value="cancel" class="btn btn-ghost btn-sm">Cancel</button></form><?php endif;?><form method="post" onsubmit="return confirm('Remove this recommendation? Paid orders are archived, never erased.')"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?=(int)$order['id']?>"><button name="action" value="delete" class="btn btn-red btn-sm"><?=$paid?'Archive':'Delete unpaid'?></button></form></div></article><?php endforeach;else:?><div class="empty"><strong>No recommendation orders match these filters.</strong><p>Owner purchases appear here as soon as they are created.</p></div><?php endif;?></section>
